{
  "findings": [
    {
      "check_id": "CKV_GCP_37",
      "title": "Ensure VM disks for critical VMs are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The disk is not encrypted with a Customer Supplied Encryption Key (CSEK), which may not be a requirement but is a security best practice for sensitive data."
    }
  ],
  "patched_code": "resource \"google_compute_disk\" \"changeme_count_attached_disk_disk\" {\n  name                      = \"changeme-count-attached-disk-disk-${count.index}\"\n  count                     = var.changeme_google_attached_disk_count_number_of_instances\n  type                      = \"pd-ssd\"\n  zone                      = \"us-central1-a\"\n  size                      = 4\n  physical_block_size_bytes = 4096\n  disk_encryption_key {\n    raw_key = \"\" # This should be set to a securely managed secret, not an empty string\n  }\n}",
  "fix_summary": "Added a disk_encryption_key block to enable encryption, though the raw_key should be securely managed."
}
